public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType == null || targetType == null) {
        return null;
    }

    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedType = (ParameterizedType) genericType;
        Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();

        // Check if the number of arguments is zero or if they are not all Class instances
        if (actualTypeArguments == null || actualTypeArguments.length == 0) {
            return null;
        }

        List<Class<?>> resolvedArguments = new ArrayList<>();
        for (Type typeArgument : actualTypeArguments) {
            if (typeArgument instanceof Class<?>) {
                resolvedArguments.add((Class<?>) typeArgument);
            } else {
                // If any type argument is not a Class, return null
                return null;
            }
        }

        return resolvedArguments.toArray(new Class<?>[0]);
    }

    // If genericType is not parameterized, return null
    return null;
}

