public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new NullPointerException("Input parameters cannot be null");
    }

    try {
        int len = str.length();
        int pos = lb.start();
        int offset = lb.offset();

        for (int i = 0; i < len; i++) {
            char c = str.charAt(i);
            if (c < 0x80) {
                ensureCapacity(session, lb, offset, 1);
                lb.buffer()[offset++] = (byte) c;
            } else if (c < 0x800) {
                ensureCapacity(session, lb, offset, 2);
                lb.buffer()[offset++] = (byte) (0xc0 | (c >> 6));
                lb.buffer()[offset++] = (byte) (0x80 | (c & 0x3f));
            } else if (Character.isSurrogate(c)) {
                if (i + 1 >= len) {
                    throw new IllegalArgumentException("Invalid UTF-8 sequence found");
                }
                char low = str.charAt(++i);
                if (!Character.isSurrogatePair(c, low)) {
                    throw new IllegalArgumentException("Invalid UTF-8 surrogate pair found");
                }
                ensureCapacity(session, lb, offset, 4);
                int codePoint = Character.toCodePoint(c, low);
                lb.buffer()[offset++] = (byte) (0xf0 | (codePoint >> 18));
                lb.buffer()[offset++] = (byte) (0x80 | ((codePoint >> 12) & 0x3f));
                lb.buffer()[offset++] = (byte) (0x80 | ((codePoint >> 6) & 0x3f));
                lb.buffer()[offset++] = (byte) (0x80 | (codePoint & 0x3f));
            } else {
                ensureCapacity(session, lb, offset, 3);
                lb.buffer()[offset++] = (byte) (0xe0 | (c >> 12));
                lb.buffer()[offset++] = (byte) (0x80 | ((c >> 6) & 0x3f));
                lb.buffer()[offset++] = (byte) (0x80 | (c & 0x3f));
            }
        }

        lb.limit(offset);
        return lb;
    } catch (Exception e) {
        throw new RuntimeException("Failed to write UTF-8 to LinkedBuffer", e);
    }
}

private static void ensureCapacity(final WriteSession session, final LinkedBuffer lb, final int offset, final int required) {
    if (offset + required > lb.buffer().length) {
        byte[] newBuffer = new byte[session.nextBufferSize(lb)];
        System.arraycopy(lb.buffer(), 0, newBuffer, 0, lb.limit());
        lb.buffer(newBuffer);
    }
}

