public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }

    String path = u.getRawPath();
    if (path == null || path.isEmpty()) {
        return pathSegments;
    }

    // If the path is absolute, ignore the leading '/'
    int start = path.startsWith("/") ? 1 : 0;

    for (String segment : path.substring(start).split("/")) {
        String decodedSegment = segment;
        if (decode) {
            try {
                decodedSegment = URLDecoder.decode(segment, StandardCharsets.UTF_8.toString());
            } catch (UnsupportedEncodingException e) {
                throw new RuntimeException("UTF-8 encoding is not supported", e);
            }
        }
        pathSegments.add(new PathSegmentImpl(decodedSegment, false));
    }

    return pathSegments;
}

