private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        if (descriptor.charAt(0) == '(') { // Method descriptor
            int end = descriptor.indexOf(')');
            if (end == -1) {
                throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
            }
            String argumentTypes = descriptor.substring(1, end);
            int index = 0;
            while (index < argumentTypes.length()) {
                char c = argumentTypes.charAt(index);
                switch (c) {
                    case 'B':
                    case 'C':
                    case 'D':
                    case 'F':
                    case 'I':
                    case 'S':
                    case 'Z':
                        index++;
                        break;
                    case 'J':
                        index += 2; // long and double take two slots
                        break;
                    case 'L': // Object type
                    case '[': // Array type
                        index = argumentTypes.indexOf(';', index) + 1;
                        if (index == 0) {
                            throw new IllegalArgumentException("Invalid object or array type in descriptor");
                        }
                        break;
                    default:
                        throw new IllegalArgumentException("Invalid type character in descriptor: " + c);
                }
            }
        } else { // Field descriptor
            char c = descriptor.charAt(0);
            switch (c) {
                case 'B':
                case 'C':
                case 'D':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                    break;
                case 'J':
                    break;
                case 'L': // Object type
                case '[': // Array type
                    if (descriptor.indexOf(';') != descriptor.length() - 1) {
                        throw new IllegalArgumentException("Invalid object or array type in descriptor");
                    }
                    break;
                default:
                    throw new IllegalArgumentException("Invalid type character in descriptor: " + c);
            }
        }
    } catch (StringIndexOutOfBoundsException | IllegalArgumentException e) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }
}

