    if (size == 0) {
        return; // No need to enlarge if no additional space is required
    }
    int neededCapacity = (this.data == null ? 0 : this.data.length) + size;
    byte[] newData = new byte[Math.max(neededCapacity, 2 * (this.data == null ? 0 : this.data.length))];
    if (this.data != null) {
