        throw new IllegalArgumentException("InputStream cannot be null");
    }
    try {
        byte[] buffer = new byte[in.available()];
        int totalBytesRead = 0;
        int bytesRead;
        while ((bytesRead = in.read(buffer, totalBytesRead, buffer.length - totalBytesRead)) != -1) {
            totalBytesRead += bytesRead;
            if (totalBytesRead >= buffer.length) {
                byte[] newBuffer = new byte[buffer.length * 2];
                System.arraycopy(buffer, 0, newBuffer, 0, buffer.length);
                buffer = newBuffer;
            }
        }
        // Trim the buffer to the actual size
        byte[] trimmedBuffer = new byte[totalBytesRead];
        System.arraycopy(buffer, 0, trimmedBuffer, 0, totalBytesRead);
        // Assuming there is a field named 'buffer' in the ClassFileBuffer class
        this.buffer = trimmedBuffer;
    } finally {
        in.close();
    }
}

