public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < str.length(); i++) {
        char currentChar = str.charAt(i);

        if (currentChar == '\\') {
            if (i + 1 >= str.length()) {
                throw new Exception("Invalid escape sequence at the end of string");
            }
            char nextChar = str.charAt(i + 1);
            switch (nextChar) {
                case 'b':
                    result.append('\b');
                    i++;
                    break;
                case 't':
                    result.append('\t');
                    i++;
                    break;
                case 'n':
                    result.append('\n');
                    i++;
                    break;
                case 'f':
                    result.append('\f');
                    i++;
                    break;
                case 'r':
                    result.append('\r');
                    i++;
                    break;
                case '\"':
                    result.append('\"');
                    i++;
                    break;
                case '\'':
                    result.append('\'');
                    i++;
                    break;
                case '\\':
                    result.append('\\');
                    i++;
                    break;
                case 'u':
                    if (i + 5 <= str.length()) {
                        try {
                            String hex = str.substring(i + 2, i + 6);
                            int codePoint = Integer.parseInt(hex, 16);
                            result.append((char) codePoint);
                            i += 5;
                        } catch (NumberFormatException e) {
                            throw new Exception("Invalid Unicode escape sequence at position " + i);
                        }
                    } else {
                        throw new Exception("Invalid Unicode escape sequence at position " + i);
                    }
                    break;
                default:
                    throw new Exception("Invalid escape sequence at position " + i);
            }
        } else {
            result.append(currentChar);
        }
    }
    return result.toString();
}

