private int removeUnusedNodesHelper(CategoryNode node) {
    if (node == null || node.isLeaf() && !node.isActive()) {
        return 0;
    }

    List<CategoryNode> children = node.getChildren();
    List<CategoryNode> toRemove = new ArrayList<>();

    for (CategoryNode child : children) {
        int removedCount = removeUnusedNodesHelper(child);
        if (!child.isActive() && child.getChildren().isEmpty()) {
            toRemove.add(child);
        }
        node.incrementRemovedCount(removedCount);
    }

    children.removeAll(toRemove);
    int removedCount = toRemove.size();

    if (!node.isActive() && node.getChildren().isEmpty()) {
        return removedCount + 1;
    }

    return removedCount;
}

