public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    try {
        if (byteLength < 0) {
            throw new IllegalArgumentException("byteLength must be non-negative");
        }
        if (byteOffset < 0 || (byteArrayValue != null && byteOffset > byteArrayValue.length - byteLength)) {
            throw new IllegalArgumentException("Invalid byteOffset or byteLength");
        }
        if (byteLength == 0) {
            return this; // Nothing to copy
        }
        if (byteArrayValue == null) {
            ensureCapacity(byteLength);
            for (int i = 0; i < byteLength; i++) {
                data[count++] = 0;
            }
        } else {
            ensureCapacity(byteLength);
            System.arraycopy(byteArrayValue, byteOffset, data, count, byteLength);
            count += byteLength;
        }
    } catch (Exception e) {
        // Handle exceptions as appropriate, e.g., log and rethrow
        throw new RuntimeException("Failed to put byte array into vector", e);
    }
    return this;
}

private void ensureCapacity(int additionalCapacity) {
    int newSize = count + additionalCapacity;
    if (newSize > data.length) {
        int oldCapacity = data.length;
        int newCapacity = oldCapacity + (oldCapacity >> 1); // Increase by 50%
        if (newCapacity < newSize) {
            newCapacity = newSize;
        }
        byte[] newData = new byte[newCapacity];
        System.arraycopy(data, 0, newData, 0, count);
        data = newData;
    }
}

