public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    // Normalize the paths by removing trailing slashes
    path = path.replaceAll("/+$", "");
    relativePath = relativePath.replaceAll("^/+", "");

    // Tokenize the relative path
    String[] tokens = relativePath.split("/");

    // Tokenize the path
    String[] pathTokens = path.split("/");

    // Use a list to handle the path tokens for easier manipulation
    List<String> pathList = new ArrayList<>(Arrays.asList(pathTokens));

    for (String token : tokens) {
        if (token.equals("..")) {
            // Move up one directory if possible
            if (!pathList.isEmpty()) {
                pathList.remove(pathList.size() - 1);
            }
        } else if (token.equals(".")) {
            // Current directory, do nothing
            continue;
        } else {
            // Add the directory or file to the path
            pathList.add(token);
        }
    }

    // Join the path list back into a string
    return String.join("/", pathList);
}

